<script>(function(){function sync(k){var t=document.querySelector('[data-wg-toggle="'+k+'"]'),s=document.querySelector('[data-wg-section="'+k+'"]');if(!t||!s)return;s.classList.toggle('wg-disabled',!t.checked);var label=t.closest('.wg-switch-label');if(label)label.firstChild.nodeValue=(t.checked?'Til ':'Fra ');}['welcome','goodbye'].forEach(function(k){var t=document.querySelector('[data-wg-toggle="'+k+'"]');if(t)t.addEventListener('change',function(){sync(k)});sync(k);});})();</script>